import fs from 'node:fs';import vm from 'node:vm';import assert from 'node:assert/strict';
const w={};vm.runInNewContext(fs.readFileSync(new URL('../students/explorer-models.js',import.meta.url),'utf8'),{window:w});const M=w.MT_EXPLORERS;let checks=0;const ok=(v,s)=>{assert.ok(v,s);checks++},near=(a,b,s,tol=1e-9)=>ok(Number.isFinite(a)&&Math.abs(a-b)<=tol*Math.max(1,Math.abs(b)),s),bad=(fn,s)=>{assert.throws(fn);checks++};
const r={r:100,l:.1,cMicro:10,voltage:1,frequency:1/(2*Math.PI*Math.sqrt(1e-6))},z=M.rlc(r);near(z.selected.z,100,'At resonance reactive voltages cancel');near(z.selected.current,.01,'One volt across100ohm gives10mA');near(z.selected.phase,0,'Resonant phase');near(M.rlc({...r,r:200}).q,z.q/2,'Double resistance halves Q');near(z.bandwidth,159.15494309189535,'Series half-power bandwidth from independently chosen L/R');const half=(sign)=>{const w0=2*Math.PI*z.f0,rr=r.r/r.l,om=(sign*rr+Math.sqrt(rr*rr+4*w0*w0))/2;return M.rlc({...r,frequency:om/(2*Math.PI)}).selected.current};near(half(1),.01/Math.sqrt(2),'Upper half-power current');near(half(-1),.01/Math.sqrt(2),'Lower half-power current');bad(()=>M.rlc({...r,r:0}),'Lossless singular resonance rejected');
const hp={hotIn:80,coldIn:20,mHot:1,mCold:1,cpHot:4,cpCold:4,ua:4,flow:'counter'},h=M.heat(hp);near(h.eps,.5,'Equal-capacity counterflow NTU1 effectiveness');near(h.duty,120,'4kW/K streams and30K change give120kW');near(h.hotOut,50,'Hot energy balance');near(h.coldOut,50,'Counterflow cold outlet');near(h.lmtd,30,'Equal terminal-difference LMTD limit');near(h.duty,hp.ua*h.lmtd,'UA-LMTD independently agrees with epsilon-NTU');
for(const flow of ['counter','parallel'])for(const mCold of [.2,1,4])for(const ua of [0,.01,1,10]){const p={...hp,mCold,ua,flow},x=M.heat(p),a=x.rows[0],b=x.rows.at(-1);near(a.hot,p.hotIn,'Hot profile inlet');near(b.hot,x.hotOut,'Hot profile outlet');near(flow==='counter'?b.cold:a.cold,p.coldIn,'Cold profile inlet direction');near(flow==='counter'?a.cold:b.cold,x.coldOut,'Cold profile outlet direction');near(x.ch*(p.hotIn-x.hotOut),x.cc*(x.coldOut-p.coldIn),'Independent stream energy closure');ok(x.rows.every(r=>r.hot>=r.cold-1e-8),'No local temperature crossing');ok(x.eps>=0&&x.eps<=1,'Effectiveness physical range');if(ua>0)near(x.duty,ua*x.lmtd,'Different capacity-rate UA-LMTD closure')}
const par=M.heat({...hp,flow:'parallel'});near(par.eps,(1-Math.exp(-2))/2,'Parallel analytical solution');ok(par.eps<h.eps,'Counterflow better at matched conditions');bad(()=>M.heat({...hp,hotIn:20}),'Zero driving difference rejected');bad(()=>M.heat({...hp,ua:10000}),'Unsupported NTU rejected');
const np={course:0,stw:10,set:90,drift:2,hours:3},nav=M.current(np);near(nav.ground.east,2,'East current component');near(nav.ground.north,10,'North through-water component');near(nav.rows.at(-1).groundEast,6,'Three-hour east drift');near(nav.rows.at(-1).groundNorth,30,'Three-hour north displacement');near(nav.cog,11.309932474020213,'Independent right-triangle bearing');near(nav.sog,Math.sqrt(104),'Ground velocity magnitude');ok(M.current({...np,stw:2,set:180}).cog===null,'Opposing equal velocities have undefined COG');bad(()=>M.current({...np,hours:0}),'Nonpositive duration rejected');
const fp={investment:100,annual:60,rate:0,years:2};near(M.finance(fp).npv,20,'Zero-rate direct sum');near(M.finance({...fp,rate:10}).npv,60/1.1+60/1.21-100,'End-year cash discounting');ok(M.finance(fp).payback===2,'Whole-year payment recovery');ok(M.finance({...fp,annual:-10}).payback===null,'Negative annual flow has no recovery');near(M.finance({...fp,rate:-10}).npv,60/.9+60/.81-100,'Negative-rate arithmetic');bad(()=>M.finance({...fp,years:2.5}),'Fractional lifetime rejected');for(const model of ['rlc','heat','current','finance'])bad(()=>M[model]({rlc:r,heat:hp,current:np,finance:fp}[model]&&{...{rlc:r,heat:hp,current:np,finance:fp}[model],[{rlc:'r',heat:'ua',current:'stw',finance:'rate'}[model]]:NaN}),model+' nonfinite input rejected');
console.log(JSON.stringify({status:'PASS',checks,scope:'Independent resonance, half-power, exchanger analytical/energy/profile, vector and cash-flow boundary cases'}));
